package solution

import "errors"

var ErrNotFound = errors.New("not found")

type RetryableError struct{ After int }

func (e *RetryableError) Error() string { return "retry later" }

// Classify inspects the error chain and maps it to a status code.
func Classify(err error) (code int, retryAfter int) {
	if errors.Is(err, ErrNotFound) { // sentinel match anywhere in the chain
		return 404, 0
	}
	var re *RetryableError
	if errors.As(err, &re) { // type match; extracts the typed error
		return 503, re.After
	}
	return 500, 0 // unknown error
}

